'use strict';
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const PORT = Number(process.env.PORT) || 3000;
const PUBLIC_DIR = path.join(__dirname, 'public');

// Scope is frozen: one voice, one model, one ElevenLabs endpoint (text-to-speech).
const VOICE_ID = 'JBFqnCBsd6RMkjVDRZzb';
const MODEL_ID = 'eleven_flash_v2_5';
const TTS_URL = `https://api.elevenlabs.io/v1/text-to-speech/${VOICE_ID}?output_format=mp3_44100_128`;
const MAX_CHARS = 500;
const MAX_BODY = 8 * 1024;

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.png': 'image/png',
};

function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    'Cache-Control': 'no-store',
  });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error('Request body too large'), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleSpeak(req, res) {
  const apiKey = process.env.ELEVENLABS_API_KEY;
  if (!apiKey) {
    return sendJson(res, 500, { error: 'Server is missing the ELEVENLABS_API_KEY environment variable.' });
  }

  let payload;
  try {
    payload = JSON.parse(await readBody(req));
  } catch (e) {
    const status = e.status || 400;
    return sendJson(res, status, { error: status === 413 ? 'Request body too large.' : 'Invalid JSON body.' });
  }

  const text = typeof payload.text === 'string' ? payload.text.trim() : '';
  if (!text) return sendJson(res, 400, { error: 'Please type a greeting first.' });
  if (text.length > MAX_CHARS) {
    return sendJson(res, 400, { error: `Greeting is too long (max ${MAX_CHARS} characters).` });
  }

  let upstream;
  try {
    upstream = await fetch(TTS_URL, {
      method: 'POST',
      headers: {
        'xi-api-key': apiKey,
        'Content-Type': 'application/json',
        Accept: 'audio/mpeg',
      },
      body: JSON.stringify({ text, model_id: MODEL_ID }),
      signal: AbortSignal.timeout(30000),
    });
  } catch (e) {
    return sendJson(res, 502, { error: 'Could not reach ElevenLabs. Please try again.' });
  }

  if (!upstream.ok) {
    let detail = '';
    try {
      const j = await upstream.json();
      const d = j && j.detail;
      detail = typeof d === 'string' ? d : (d && d.message) || '';
    } catch (_) { /* ignore */ }
    const hint = upstream.status === 401 ? 'ElevenLabs rejected the API key.' : 'ElevenLabs request failed.';
    return sendJson(res, 502, {
      error: `${hint} (status ${upstream.status})${detail ? ': ' + detail : ''}`,
    });
  }

  const audio = Buffer.from(await upstream.arrayBuffer());
  res.writeHead(200, {
    'Content-Type': 'audio/mpeg',
    'Content-Length': audio.length,
    'Cache-Control': 'no-store',
  });
  res.end(audio);
}

function serveStatic(req, res, pathname) {
  let rel;
  try {
    rel = decodeURIComponent(pathname);
  } catch (_) {
    res.writeHead(400);
    return res.end('Bad request');
  }
  if (rel.endsWith('/')) rel += 'index.html';
  const filePath = path.normalize(path.join(PUBLIC_DIR, rel));
  if (filePath !== PUBLIC_DIR && !filePath.startsWith(PUBLIC_DIR + path.sep)) {
    res.writeHead(403);
    return res.end('Forbidden');
  }
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      return res.end('Not found');
    }
    res.writeHead(200, {
      'Content-Type': MIME[path.extname(filePath).toLowerCase()] || 'application/octet-stream',
    });
    res.end(data);
  });
}

const server = http.createServer(async (req, res) => {
  try {
    const { pathname } = new URL(req.url, 'http://localhost');
    if (pathname.startsWith('/api/')) {
      if (pathname === '/api/speak') {
        if (req.method !== 'POST') {
          res.setHeader('Allow', 'POST');
          return sendJson(res, 405, { error: 'Use POST.' });
        }
        return await handleSpeak(req, res);
      }
      return sendJson(res, 404, { error: 'Unknown API route.' });
    }
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      res.writeHead(405);
      return res.end('Method not allowed');
    }
    serveStatic(req, res, pathname);
  } catch (e) {
    if (!res.headersSent) sendJson(res, 500, { error: 'Internal server error.' });
    else res.end();
  }
});

server.listen(PORT, () => {
  console.log(`Listening on port ${PORT}` + (process.env.ELEVENLABS_API_KEY ? '' : ' (ELEVENLABS_API_KEY is not set)'));
});

'use strict';
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const PORT = process.env.PORT || 3000;
const PUBLIC_DIR = path.join(__dirname, 'public');

// Scope frozen by the team brief: one voice, one model, one ElevenLabs endpoint (text-to-speech).
const VOICE_ID = 'JBFqnCBsd6RMkjVDRZzb';
const MODEL_ID = 'eleven_flash_v2_5';
const SPEED = 0.7; // slowest speed ElevenLabs allows (range 0.7 - 1.2)
const MAX_CHARS = 100;

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
};

const cache = new Map(); // text -> Buffer (small in-memory cache so repeated words cost nothing)
const CACHE_MAX = 100;

function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(body);
}

function readBody(req, limit = 4096) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > limit) {
        reject(Object.assign(new Error('Request too large'), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleSpeak(req, res) {
  const key = process.env.ELEVENLABS_API_KEY;
  if (!key) {
    return sendJson(res, 500, { error: 'Server is missing the ELEVENLABS_API_KEY environment variable.' });
  }

  let text;
  try {
    const parsed = JSON.parse(await readBody(req));
    text = typeof parsed.text === 'string' ? parsed.text.trim().replace(/\s+/g, ' ') : '';
  } catch (e) {
    return sendJson(res, e.status || 400, { error: e.status === 413 ? 'Request too large.' : 'Invalid JSON body.' });
  }
  if (!text) return sendJson(res, 400, { error: 'Please type a word or name first.' });
  if (text.length > MAX_CHARS) return sendJson(res, 400, { error: `Please keep it under ${MAX_CHARS} characters.` });

  const cacheKey = text.toLowerCase();
  let audio = cache.get(cacheKey);
  if (!audio) {
    try {
      const url = `https://api.elevenlabs.io/v1/text-to-speech/${VOICE_ID}?output_format=mp3_44100_128`;
      const r = await fetch(url, {
        method: 'POST',
        headers: {
          'xi-api-key': key,
          'Content-Type': 'application/json',
          Accept: 'audio/mpeg',
        },
        body: JSON.stringify({
          text,
          model_id: MODEL_ID,
          voice_settings: { stability: 0.6, similarity_boost: 0.75, speed: SPEED },
        }),
        signal: AbortSignal.timeout(20000),
      });
      if (!r.ok) {
        console.error(`ElevenLabs responded with HTTP ${r.status}`);
        const msg = r.status === 401
          ? 'ElevenLabs rejected the API key.'
          : r.status === 429
            ? 'ElevenLabs rate limit reached. Try again shortly.'
            : `ElevenLabs request failed (HTTP ${r.status}).`;
        return sendJson(res, 502, { error: msg });
      }
      audio = Buffer.from(await r.arrayBuffer());
      if (!audio.length) return sendJson(res, 502, { error: 'ElevenLabs returned empty audio.' });
      if (cache.size >= CACHE_MAX) cache.delete(cache.keys().next().value);
      cache.set(cacheKey, audio);
    } catch (e) {
      console.error('ElevenLabs call failed:', e.name);
      return sendJson(res, 502, { error: 'Could not reach ElevenLabs. Try again.' });
    }
  }

  res.writeHead(200, {
    'Content-Type': 'audio/mpeg',
    'Content-Length': audio.length,
    'Cache-Control': 'no-store',
  });
  res.end(audio);
}

function serveStatic(req, res) {
  let pathname;
  try {
    pathname = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
  } catch {
    res.writeHead(400);
    return res.end('Bad request');
  }
  if (pathname.endsWith('/')) pathname += 'index.html';
  const filePath = path.normalize(path.join(PUBLIC_DIR, pathname));
  if (filePath !== PUBLIC_DIR && !filePath.startsWith(PUBLIC_DIR + path.sep)) {
    res.writeHead(403);
    return res.end('Forbidden');
  }
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      return res.end('Not found');
    }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(filePath)] || 'application/octet-stream' });
    res.end(data);
  });
}

const server = http.createServer(async (req, res) => {
  try {
    const pathname = new URL(req.url, 'http://localhost').pathname;
    if (pathname.startsWith('/api/')) {
      if (pathname === '/api/speak' && req.method === 'POST') return await handleSpeak(req, res);
      if (pathname === '/api/speak') return sendJson(res, 405, { error: 'Use POST.' });
      return sendJson(res, 404, { error: 'Unknown API route.' });
    }
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      res.writeHead(405);
      return res.end('Method not allowed');
    }
    serveStatic(req, res);
  } catch (e) {
    console.error('Unhandled error:', e.message);
    if (!res.headersSent) sendJson(res, 500, { error: 'Internal server error.' });
    else res.end();
  }
});

server.listen(PORT, () => console.log(`Pronunciation helper listening on port ${PORT}`));
